 let obj;try {obj=JSON.parse(raw.slice(first,last+1));} catch {return {ok:false,reason:'unparsable-json'};}
 for(const field of ['ticketId','category']) {
  if(obj[field] == null)return {ok:false,reason:'missing-field'};
