 }
 if(obj.confidence == null)return {ok:false,reason:'missing-field'};
 if(!Number.isFinite(obj.confidence))return {ok:false,reason:'wrong-type'};
 if(obj.confidence<0||obj.confidence>1)return {ok:false,reason:'confidence-out-of-range'};
